import { useEffect, useId, useRef, useSyncExternalStore } from "react";
import {
  Avatar,
  Badge,
  Button,
  Calendar,
  Fieldset,
  FormField,
  Heading,
  Input,
  Select,
  Spinner,
  Textarea,
  Text,
} from "@paraxe/react";
import {
  bookingCalendarEvent,
  bookingDestination,
  bookingTime,
  bookingWhen,
  type Booking01Props,
} from "../shared/booking";
import "../shared/booking.css";
export function Booking01({
  controller,
  title = "A little time. A clearer direction.",
  description = "Choose a moment to pause, talk it through, and work out what comes next.",
  backHref,
  refresh,
}: Booking01Props) {
  const id = `booking-${useId()}`,
    state = useSyncExternalStore(
      controller.subscribe,
      controller.getSnapshot,
      controller.getSnapshot,
    ),
    { data } = state,
    available = controller.availability(),
    selected = available.selected,
    destination = bookingDestination(backHref);
  const stage = useRef<HTMLHeadingElement>(null),
    form = useRef<HTMLFormElement>(null),
    previous = useRef(state.phase);
  useEffect(() => {
    if (previous.current !== state.phase) {
      stage.current?.focus();
      previous.current = state.phase;
    }
  }, [state.phase]);
  useEffect(() => {
    const first = Object.keys(state.errors)[0];
    if (first)
      form.current?.querySelector<HTMLElement>(`[name="${first}"]`)?.focus();
  }, [state.errors]);
  const day = new Intl.DateTimeFormat(data.locale, {
    weekday: "long",
    day: "numeric",
    month: "long",
    timeZone: "UTC",
  }).format(new Date(`${state.date}T12:00:00Z`));
  return (
    <section className="booking01" aria-labelledby={`${id}-title`}>
      <div className="booking01-inner">
        <header className="booking01-top">
          <span>{data.brand}</span>
          <p>A GOOD CONVERSATION STARTS HERE</p>
          {destination && (
            <a href={destination}>
              Back to the studio <span aria-hidden="true">↗</span>
            </a>
          )}
        </header>
        <div className="booking01-intro">
          <div>
            <p className="booking01-eyebrow">Make room for the next step</p>
            <Heading level="h1" id={`${id}-title`}>
              {title}
            </Heading>
          </div>
          <Text className="booking01-copy">{description}</Text>
        </div>
        <div className="booking01-canvas">
          <aside className="booking01-brief" aria-labelledby={`${id}-service`}>
            <div className="booking01-host">
              <Avatar
                name={data.host.name}
                src={data.host.imageSrc}
                size="lg"
                alt=""
              />
              <div>
                <strong>{data.host.name}</strong>
                <p>{data.host.role}</p>
              </div>
            </div>
            <p className="booking01-eyebrow">One focused session</p>
            <Heading level="h2" id={`${id}-service`}>
              {data.title}
            </Heading>
            <Text className="booking01-copy">{data.description}</Text>
            <dl className="booking01-facts">
              <div>
                <dt>Duration</dt>
                <dd>{data.durationMinutes} minutes</dd>
              </div>
              <div>
                <dt>Where</dt>
                <dd>{data.location}</dd>
              </div>
              <div>
                <dt>Language</dt>
                <dd>{data.language}</dd>
              </div>
            </dl>
            <div className="booking01-agenda">
              <h3>What we'll make room for</h3>
              <ol>
                {data.agenda.map((line, index) => (
                  <li key={index}>
                    <span aria-hidden="true">0{index + 1}</span>
                    {line}
                  </li>
                ))}
              </ol>
            </div>
            <FormField
              id={`${id}-zone`}
              label="Your time zone"
              disabled={state.pending || state.phase === "confirmed"}
            >
              {(control) => (
                <Select
                  {...control}
                  modelValue={state.timeZone}
                  onModelValueChange={controller.setTimeZone}
                >
                  {data.timeZones.map((zone) => (
                    <option key={zone.value} value={zone.value}>
                      {zone.label}
                    </option>
                  ))}
                </Select>
              )}
            </FormField>
            <p className="booking01-zone-note">
              Dates and times adapt to your time zone.
            </p>
          </aside>
          <div
            className="booking01-stage"
            aria-busy={state.pending || undefined}
          >
            <header className="booking01-stage-heading">
              <p className="booking01-eyebrow">
                {state.phase === "choose"
                  ? "01 / Find your moment"
                  : state.phase === "details"
                    ? "02 / Make it personal"
                    : "03 / All set"}
              </p>
              <h2 ref={stage} tabIndex={-1}>
                {state.phase === "choose"
                  ? "Choose your time."
                  : state.phase === "details"
                    ? "Tell us a little about you."
                    : "You’re booked."}
              </h2>
            </header>
            {state.phase === "choose" && (
              <>
                {available.dates.length ? (
                  <div className="booking01-picker">
                    <div className="booking01-calendar">
                      <Calendar
                        modelValue={state.date}
                        min={available.dates[0]}
                        max={available.dates[available.dates.length - 1]}
                        availableDates={available.dates}
                        locale={data.locale}
                        label="Choose an available appointment date"
                        onModelValueChange={controller.setDate}
                      />
                      <p className="booking01-legend">
                        <span aria-hidden="true" />
                        Dates with a dot have available times.
                      </p>
                    </div>
                    <section
                      className="booking01-times"
                      aria-labelledby={`${id}-times`}
                    >
                      <h3 id={`${id}-times`} aria-live="polite">
                        {day}
                      </h3>
                      <p>
                        {available.slots.length} available{" "}
                        {available.slots.length === 1 ? "time" : "times"}
                      </p>
                      <div
                        className="booking01-time-list"
                        role="group"
                        aria-labelledby={`${id}-times`}
                      >
                        {available.slots.map((slot) => {
                          const label = bookingTime(
                            slot.start,
                            state.timeZone,
                            data.locale,
                          );
                          return (
                            <button
                              type="button"
                              key={slot.id}
                              className="booking01-time"
                              aria-pressed={state.slotId === slot.id}
                              aria-label={bookingWhen(
                                slot.start,
                                state.timeZone,
                                data.locale,
                              )}
                              onClick={() => controller.choose(slot.id)}
                            >
                              <span>{label.time}</span>
                              <small>{label.offset}</small>
                              <span aria-hidden="true">↗</span>
                            </button>
                          );
                        })}
                      </div>
                      {!available.slots.length && (
                        <Text className="booking01-copy">
                          No times remain on this date. Choose another date.
                        </Text>
                      )}
                      <p className="booking01-time-note">
                        {data.durationMinutes} minutes, one conversation.
                      </p>
                    </section>
                  </div>
                ) : (
                  <div className="booking01-empty" role="status">
                    <Heading level="h3">
                      The next dates are on their way.
                    </Heading>
                    <Text className="booking01-copy">
                      There are no available times in this schedule.
                    </Text>
                    {refresh && (
                      <Button variant="secondary" onActivate={refresh}>
                        Refresh availability
                      </Button>
                    )}
                  </div>
                )}
              </>
            )}
            {state.phase === "details" && selected && (
              <div className="booking01-details">
                <div className="booking01-selected">
                  <p>YOUR MOMENT</p>
                  <strong>
                    {bookingWhen(selected.start, state.timeZone, data.locale)}
                  </strong>
                  <span>
                    {data.durationMinutes} minutes · {data.location}
                  </span>
                  <Button
                    variant="text"
                    size="small"
                    disabled={state.pending}
                    onActivate={controller.back}
                  >
                    Choose another time
                  </Button>
                </div>
                <form
                  ref={form}
                  noValidate
                  onSubmit={(event) => {
                    event.preventDefault();
                    void controller.confirm();
                  }}
                >
                  <Fieldset
                    legend="Your details"
                    disabled={state.pending}
                    className="booking01-fields"
                  >
                    <FormField
                      id={`${id}-name`}
                      label="Your name"
                      required
                      error={state.errors.name}
                      disabled={state.pending}
                    >
                      {(control) => (
                        <Input
                          {...control}
                          name="name"
                          autocomplete="name"
                          modelValue={state.details.name}
                          onModelValueChange={(next) =>
                            controller.edit("name", next)
                          }
                        />
                      )}
                    </FormField>
                    <FormField
                      id={`${id}-email`}
                      label="Email address"
                      required
                      error={state.errors.email}
                      disabled={state.pending}
                    >
                      {(control) => (
                        <Input
                          {...control}
                          name="email"
                          type="email"
                          autocomplete="email"
                          modelValue={state.details.email}
                          onModelValueChange={(next) =>
                            controller.edit("email", next)
                          }
                        />
                      )}
                    </FormField>
                    <FormField
                      id={`${id}-notes`}
                      label="What would you like to talk through?"
                      optional
                      description="A little context helps us prepare. Up to 2,000 characters."
                      error={state.errors.notes}
                      disabled={state.pending}
                    >
                      {(control) => (
                        <Textarea
                          {...control}
                          name="notes"
                          rows={4}
                          maxlength={2000}
                          modelValue={state.details.notes}
                          onModelValueChange={(next) =>
                            controller.edit("notes", next)
                          }
                        />
                      )}
                    </FormField>
                  </Fieldset>
                  <div className="booking01-form-actions">
                    <Button type="submit" disabled={state.pending}>
                      {state.pending && <Spinner size="sm" label="" />}
                      {state.pending
                        ? "Confirming your time…"
                        : "Confirm this time"}
                      {!state.pending && <span aria-hidden="true">↗</span>}
                    </Button>
                    <p>Your time is booked after confirmation.</p>
                  </div>
                </form>
              </div>
            )}
            {state.phase === "confirmed" && state.confirmation && (
              <div className="booking01-confirmed">
                <div className="booking01-confirm-mark" aria-hidden="true">
                  ✓
                </div>
                <Badge>Time well made</Badge>
                <Heading level="h3">
                  See you there, {state.details.name.trim().split(/\s+/)[0]}.
                </Heading>
                <Text className="booking01-copy">
                  {bookingWhen(
                    state.confirmation.start,
                    state.timeZone,
                    data.locale,
                  )}
                </Text>
                <dl>
                  <div>
                    <dt>Session</dt>
                    <dd>{data.title}</dd>
                  </div>
                  <div>
                    <dt>With</dt>
                    <dd>{data.host.name}</dd>
                  </div>
                  <div>
                    <dt>Duration</dt>
                    <dd>{data.durationMinutes} minutes</dd>
                  </div>
                  <div>
                    <dt>Reference</dt>
                    <dd>{state.confirmation.id}</dd>
                  </div>
                </dl>
                <div className="booking01-confirm-actions">
                  <a
                    className="booking01-calendar-download"
                    download={`appointment-${data.id}.ics`}
                    href={`data:text/calendar;charset=utf-8,${encodeURIComponent(bookingCalendarEvent(data, state.confirmation))}`}
                  >
                    Download calendar event <span aria-hidden="true">↗</span>
                  </a>
                  {state.confirmation.joinHref && (
                    <a href={state.confirmation.joinHref}>Open meeting link</a>
                  )}
                  <Button variant="text" onActivate={controller.reset}>
                    Book another time
                  </Button>
                </div>
              </div>
            )}
            {state.message && (
              <p
                className="booking01-feedback"
                role={state.failed ? "alert" : "status"}
              >
                {state.message}
              </p>
            )}
          </div>
        </div>
        <footer className="booking01-footer">
          <span>{data.brand}</span>
          <p>A little room for a better next step.</p>
          <span>CHOOSE / INTRODUCE / CONFIRM</span>
        </footer>
      </div>
    </section>
  );
}

import { calendarAddDays, calendarDateKey, isCalendarDate } from "@paraxe/core";
export interface BookingSlot {
  id: string;
  start: string;
  available: boolean;
}
export interface BookingRecord {
  id: string;
  brand: string;
  title: string;
  description: string;
  host: { name: string; role: string; imageSrc?: string };
  durationMinutes: number;
  location: string;
  language: string;
  agenda: readonly string[];
  asOf: string;
  timeZone: string;
  timeZones: readonly { value: string; label: string }[];
  locale: string;
  slots: readonly BookingSlot[];
}
export interface BookingDetails {
  name: string;
  email: string;
  notes: string;
}
export interface BookingConfirmation {
  id: string;
  slotId: string;
  start: string;
  createdAt: string;
  joinHref?: string;
}
export interface BookingServices {
  confirm: (request: {
    requestId: string;
    serviceId: string;
    slot: BookingSlot;
    details: BookingDetails;
    timeZone: string;
  }) => Promise<BookingConfirmation>;
  now?: () => number;
  createRequestId?: () => string;
}
export interface BookingSnapshot {
  data: BookingRecord;
  phase: "choose" | "details" | "confirmed";
  timeZone: string;
  date: string;
  slotId: string | null;
  details: BookingDetails;
  errors: Partial<Record<keyof BookingDetails, string>>;
  pending: boolean;
  message: string;
  failed: boolean;
  unavailable: readonly string[];
  confirmation: BookingConfirmation | null;
}
export class BookingSlotUnavailableError extends Error {
  constructor() {
    super("The selected slot is no longer available.");
    this.name = "BookingSlotUnavailableError";
  }
}
const instant = (value: string) =>
  typeof value === "string" &&
  /T.*(?:Z|[+-]\d{2}:\d{2})$/.test(value) &&
  Number.isFinite(Date.parse(value));
export function bookingDestination(value: string | undefined) {
  if (value === undefined) return;
  const href = value.trim();
  if (
    !href ||
    /^[\\/]{2}/.test(href) ||
    new URL(href, "https://paraxe.invalid/").protocol !== "https:"
  )
    throw Error("Booking destinations must be relative or HTTPS.");
  return href;
}
export function bookingDate(start: string, timeZone: string) {
  const parts = new Intl.DateTimeFormat("en-CA", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    timeZone,
  }).formatToParts(new Date(start));
  return `${parts.find((part) => part.type === "year")!.value}-${parts.find((part) => part.type === "month")!.value}-${parts.find((part) => part.type === "day")!.value}`;
}
export function bookingTime(start: string, timeZone: string, locale = "en-GB") {
  return {
    time: new Intl.DateTimeFormat(locale, {
      hour: "2-digit",
      minute: "2-digit",
      timeZone,
    }).format(new Date(start)),
    offset:
      new Intl.DateTimeFormat(locale, { timeZone, timeZoneName: "shortOffset" })
        .formatToParts(new Date(start))
        .find((part) => part.type === "timeZoneName")?.value ?? "",
  };
}
export function bookingWhen(start: string, timeZone: string, locale = "en-GB") {
  return new Intl.DateTimeFormat(locale, {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    timeZone,
    timeZoneName: "short",
  }).format(new Date(start));
}
export function validateBooking(input: BookingRecord): BookingRecord {
  const id = (value: string) =>
      typeof value === "string" && /^[a-zA-Z0-9][a-zA-Z0-9_-]*$/.test(value),
    ids = new Set<string>(),
    instants = new Set<number>(),
    zones = new Set<string>();
  if (
    !id(input.id) ||
    !input.brand?.trim() ||
    !input.title?.trim() ||
    !input.host.name.trim() ||
    !Number.isSafeInteger(input.durationMinutes) ||
    input.durationMinutes < 1 ||
    input.durationMinutes > 1440 ||
    !instant(input.asOf)
  )
    throw Error(
      "Booking needs valid service, host, duration, and snapshot time.",
    );
  const timeZones = input.timeZones.map((zone) => {
    new Intl.DateTimeFormat(input.locale, { timeZone: zone.value });
    if (zones.has(zone.value) || !zone.label.trim())
      throw Error("Time zones need unique values and names.");
    zones.add(zone.value);
    return Object.freeze({ ...zone });
  });
  if (!zones.has(input.timeZone))
    throw Error("The default time zone must be offered.");
  const slots = input.slots
    .map((slot) => {
      const ms = Date.parse(slot.start);
      if (
        !id(slot.id) ||
        ids.has(slot.id) ||
        !instant(slot.start) ||
        instants.has(ms) ||
        typeof slot.available !== "boolean"
      )
        throw Error("Slots need unique IDs, instants and availability states.");
      ids.add(slot.id);
      instants.add(ms);
      return Object.freeze({ ...slot });
    })
    .sort((a, b) => Date.parse(a.start) - Date.parse(b.start));
  return Object.freeze({
    ...input,
    host: Object.freeze({ ...input.host }),
    agenda: Object.freeze([...input.agenda]),
    timeZones: Object.freeze(timeZones),
    slots: Object.freeze(slots),
  });
}
export function bookingAvailability(state: BookingSnapshot) {
  const slots = state.data.slots.filter(
    (slot) =>
      slot.available &&
      !state.unavailable.includes(slot.id) &&
      Date.parse(slot.start) > Date.parse(state.data.asOf),
  );
  const dates = Array.from(
    new Set(slots.map((slot) => bookingDate(slot.start, state.timeZone))),
  ).sort();
  return {
    dates,
    slots: slots.filter(
      (slot) => bookingDate(slot.start, state.timeZone) === state.date,
    ),
    selected: slots.find((slot) => slot.id === state.slotId) ?? null,
  };
}
export function bookingDetailsErrors(details: BookingDetails) {
  const errors: BookingSnapshot["errors"] = {};
  if (!details.name.trim()) errors.name = "Enter your name.";
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(details.email.trim()))
    errors.email = "Enter a contact email address.";
  if (details.notes.length > 2000)
    errors.notes = "Keep your note to 2,000 characters.";
  return errors;
}
export function validateBookingConfirmation(
  value: BookingConfirmation,
  slot: BookingSlot,
) {
  if (
    !value.id?.trim() ||
    value.slotId !== slot.id ||
    !instant(value.start) ||
    Date.parse(value.start) !== Date.parse(slot.start) ||
    !instant(value.createdAt)
  )
    throw Error("Confirmation does not match the selected appointment.");
  return Object.freeze({
    ...value,
    joinHref: bookingDestination(value.joinHref),
  });
}
export function createBookingController(
  input: BookingRecord,
  services: BookingServices,
) {
  const listeners = new Set<() => void>();
  let generation = 0,
    requestId: string | null = null;
  const start = (
    data: BookingRecord,
    unavailable: readonly string[] = [],
  ): BookingSnapshot => {
    const state: BookingSnapshot = {
      data,
      phase: "choose",
      timeZone: data.timeZone,
      date: "",
      slotId: null,
      details: { name: "", email: "", notes: "" },
      errors: {},
      pending: false,
      message: "",
      failed: false,
      unavailable,
      confirmation: null,
    };
    state.date =
      bookingAvailability(state).dates[0] ??
      bookingDate(data.asOf, data.timeZone);
    return state;
  };
  let state = start(validateBooking(input));
  const publish = (patch: Partial<BookingSnapshot>) => {
    state = Object.freeze({
      ...state,
      ...patch,
      details: Object.freeze(patch.details ?? state.details),
      errors: Object.freeze(patch.errors ?? state.errors),
      unavailable: Object.freeze([...(patch.unavailable ?? state.unavailable)]),
    });
    listeners.forEach((listener) => listener());
  };
  publish({});
  const unavailable = (id: string) => {
    requestId = null;
    const taken = Array.from(new Set([...state.unavailable, id]));
    const next = { ...state, unavailable: taken };
    const dates = bookingAvailability(next).dates;
    publish({
      unavailable: taken,
      slotId: null,
      phase: "choose",
      confirmation: null,
      pending: false,
      date: dates.includes(state.date)
        ? state.date
        : (dates[0] ?? bookingDate(state.data.asOf, state.timeZone)),
      message:
        "That time is no longer available. Choose another time; your details are kept here.",
      failed: true,
    });
  };
  return {
    getSnapshot: () => state,
    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    availability: () => bookingAvailability(state),
    setDate(date: string) {
      if (
        state.pending ||
        state.phase === "confirmed" ||
        !isCalendarDate(date) ||
        !bookingAvailability(state).dates.includes(date)
      )
        return;
      requestId = null;
      publish({
        date,
        slotId: null,
        phase: "choose",
        message: "",
        failed: false,
        errors: {},
      });
    },
    setTimeZone(timeZone: string) {
      if (
        state.pending ||
        state.phase === "confirmed" ||
        !state.data.timeZones.some((zone) => zone.value === timeZone)
      )
        return;
      if (timeZone !== state.timeZone) requestId = null;
      const next = { ...state, timeZone },
        available = bookingAvailability(next),
        selected = available.selected;
      publish({
        timeZone,
        date: selected
          ? bookingDate(selected.start, timeZone)
          : available.dates.includes(state.date)
            ? state.date
            : (available.dates[0] ?? bookingDate(state.data.asOf, timeZone)),
        message: "",
        failed: false,
      });
    },
    choose(id: string) {
      if (state.pending || state.phase === "confirmed") return;
      const slot = bookingAvailability(state).slots.find(
        (slot) => slot.id === id,
      );
      if (!slot) return;
      requestId = null;
      publish({
        slotId: id,
        phase: "details",
        message: "",
        failed: false,
        errors: {},
      });
    },
    edit(key: keyof BookingDetails, value: string) {
      if (
        state.pending ||
        state.phase === "confirmed" ||
        !Object.prototype.hasOwnProperty.call(state.details, key) ||
        typeof value !== "string"
      )
        return;
      requestId = null;
      const errors = { ...state.errors };
      delete errors[key];
      publish({
        details: { ...state.details, [key]: value },
        errors,
        message: "",
        failed: false,
      });
    },
    back() {
      if (!state.pending && state.phase === "details")
        publish({ phase: "choose", message: "", failed: false, errors: {} });
    },
    replace(input: BookingRecord) {
      const data = validateBooking(input);
      generation++;
      requestId = null;
      publish(start(data));
    },
    reset() {
      if (state.pending) return;
      generation++;
      requestId = null;
      const taken = state.confirmation
        ? Array.from(new Set([...state.unavailable, state.confirmation.slotId]))
        : state.unavailable;
      publish(start(state.data, taken));
    },
    cancelPending() {
      generation++;
      publish({ pending: false, message: "", failed: false });
    },
    async confirm() {
      if (state.pending || state.phase !== "details") return;
      const slot = bookingAvailability(state).selected;
      if (!slot) return;
      if (Date.parse(slot.start) <= (services.now ?? Date.now)()) {
        unavailable(slot.id);
        return;
      }
      const errors = bookingDetailsErrors(state.details);
      if (Object.keys(errors).length) {
        publish({
          errors,
          message: "Check the highlighted details.",
          failed: true,
        });
        return;
      }
      const request = ++generation,
        details = { ...state.details },
        data = state.data,
        timeZone = state.timeZone;
      publish({ pending: true, errors: {}, message: "", failed: false });
      try {
        requestId ??= (
