export function createSampleBooking(
  asOf = new Date().toISOString(),
): BookingRecord {
  const day = calendarDateKey(new Date(asOf)),
    weekday = new Date(`${day}T12:00:00Z`).getUTCDay(),
    monday = calendarAddDays(day, (8 - weekday) % 7 || 7),
    dates = [0, 1, 3, 4, 7, 8, 10, 11, 14, 15, 17, 18].map((offset) =>
      calendarAddDays(monday, offset),
    );
