    id: "paraxe-direction",
    brand: "Paraxe Studio",
    title: "Product direction session",
    description:
      "Bring the rough idea, the difficult question, or the thing that is not quite clicking. Leave with a clearer next step.",
    host: { name: "Alex Morgan", role: "Product designer" },
    durationMinutes: 45,
    location: "Video conversation",
