    ],
    asOf,
    timeZone: "Europe/London",
    timeZones: [
      { value: "Europe/London", label: "United Kingdom time" },
      { value: "America/New_York", label: "New York time" },
      { value: "Asia/Tokyo", label: "Tokyo time" },
    ],
    locale: "en-GB",
    slots: dates.flatMap((date, index) =>
      ["09:00", "11:30", "14:00", "16:00"].map((time, slotIndex) => ({
        id: `session-${index}-${slotIndex}`,
        start: `${date}T${time}:00Z`,
        available: !(index === 1 && slotIndex === 0),
