  };
}

/** Local calendar artifact only. This does not send invitations or update a calendar account. */
export function bookingCalendarEvent(
  data: BookingRecord,
  confirmation: BookingConfirmation,
) {
  const text = (value: string) =>
    value
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "")
      .replace(/\\/g, "\\\\")
      .replace(/\r\n|\r|\n/g, "\\n")
      .replace(/;/g, "\\;")
      .replace(/,/g, "\\,");
  const utc = (value: string | number) =>
    new Date(value)
      .toISOString()
      .replace(/[-:]/g, "")
      .replace(/\.\d{3}Z$/, "Z");
  const lines = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//Paraxe//Appointment//EN",
    "CALSCALE:GREGORIAN",
    "BEGIN:VEVENT",
    `UID:${encodeURIComponent(data.id)}.${encodeURIComponent(confirmation.id)}@paraxe.local`,
    `DTSTAMP:${utc(confirmation.createdAt)}`,
    `DTSTART:${utc(confirmation.start)}`,
    `DTEND:${utc(Date.parse(confirmation.start) + data.durationMinutes * 60000)}`,
    `SUMMARY:${text(data.title)}`,
    `DESCRIPTION:${text(data.description)}`,
    `LOCATION:${text(data.location)}`,
    "END:VEVENT",
    "END:VCALENDAR",
  ];
  const encoder = new TextEncoder();
  return (
    lines
      .map((line) => {
        const folded: string[] = [];
        let current = "",
          size = 0;
        for (const char of line) {
          const length = encoder.encode(char).length;
          if (size + length > 75) {
            folded.push(current);
            current = " ";
            size = 1;
          }
          current += char;
          size += length;
        }
        folded.push(current);
        return folded.join("\r\n");
      })
      .join("\r\n") + "\r\n"
  );
}

